-- J-LAS Flashcard: phần Từ vựng và phần Hán tự của giáo trình, mỗi bài một bộ, MySQL 8.0.16+, UTF-8.
-- GENERATED by tools/flashcard_textbook/build_seed.py from data/vnjpclub*/ and data/flashcard_textbook/. Do not edit.
-- {{TEXTBOOK_SET_COUNT}} bộ / {{TEXTBOOK_CARD_COUNT}} thẻ từ {{BOOK_COUNT}} giáo trình N5–N1, tên bộ ghi cấp Nx; bài dưới 15 thẻ
-- và bài đọc/nghe/đề luyện không làm bộ. Thẻ từ vựng: từ, cách đọc, nghĩa, âm Hán Việt của cả từ, câu ví dụ trong sách.
-- Thẻ Hán tự: chữ, âm Hán Việt, cách đọc On/Kun, nghĩa, ví dụ là từ ghép sách in kèm.
-- Chủ sở hữu: tài khoản có sẵn @flashcard_textbook_owner_email (mặc định content@jlab.local).
-- Thay dữ liệu cũ: các bộ công khai của seedsqlflashcard.sql, flashcard_demo_5_sets.sql, seed cộng đồng
-- (seed_data_flashcard_community.sql) và 'N5 giao tiếp cơ bản' của jlas_seed_all.sql bị xoá cùng bình luận;
-- bộ đã có trận game (game_match) chỉ bị ẩn (deleted_at) để giữ lịch sử trận. Bộ riêng tư của người dùng không bị đụng tới.
-- Giữ 'Hiragana cơ bản' / 'Katakana cơ bản' ({{KANA_SET_COUNT}} bộ, chỉ tạo khi DB chưa có).
-- Chạy lại an toàn: bộ giáo trình nhận diện bằng moderation_summary 'TEXTBOOK_FLASHCARD:<mã bài>' (hoặc cùng tên);
-- thẻ cập nhật theo vị trí nên tiến độ học của người dùng được giữ.
-- Chạy sau jlas_seed_all.sql (seed đó tạo lại các bộ demo cũ). Trong MySQL Workbench: Execute All.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @flashcard_textbook_owner_email = COALESCE(NULLIF(TRIM(@flashcard_textbook_owner_email), ''), 'content@jlab.local');

DROP TEMPORARY TABLE IF EXISTS fct_set;
DROP TEMPORARY TABLE IF EXISTS fct_card;
DROP TEMPORARY TABLE IF EXISTS fct_retired;
CREATE TEMPORARY TABLE fct_set (
    set_key     VARCHAR(60) NOT NULL PRIMARY KEY,
    kind        VARCHAR(10) NOT NULL,          -- TEXTBOOK | KANA
    sort_rank   INT UNSIGNED NOT NULL,         -- 0 = mới nhất trong thư viện (N5 trước)
    title       VARCHAR(100) NOT NULL,
    description VARCHAR(500) NULL,
    set_id      BIGINT UNSIGNED NULL,
    is_new      TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE fct_card (
    set_key    VARCHAR(60) NOT NULL,
    position   INT UNSIGNED NOT NULL,
    front      VARCHAR(500) NULL,
    back       VARCHAR(500) NULL,
    reading    VARCHAR(255) NULL,
    meaning    VARCHAR(500) NULL,
    han_viet   VARCHAR(255) NULL,
    jlpt_level VARCHAR(10) NULL,
    word_type  VARCHAR(50) NULL,
    example_ja TEXT NULL,
    example_vi TEXT NULL,
    PRIMARY KEY (set_key, position)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Bộ của seed cộng đồng cũ: chủ là học viên mẫu (tools/demo_learners.py, không có mật khẩu).
CREATE TEMPORARY TABLE fct_retired (
    owner_email VARCHAR(255) NOT NULL,
    title       VARCHAR(100) NOT NULL,
    PRIMARY KEY (owner_email, title)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

{{DATA}}

DROP PROCEDURE IF EXISTS jlas_seed_flashcard_textbook_v1;
DELIMITER $$
CREATE PROCEDURE jlas_seed_flashcard_textbook_v1()
SQL SECURITY INVOKER
BEGIN
    DECLARE locked INT DEFAULT 0;
    DECLARE started INT DEFAULT 0;
    DECLARE owner BIGINT UNSIGNED;
    DECLARE anchor DATETIME(6);
    DECLARE lock_name VARCHAR(64);
    DECLARE retired INT DEFAULT 0;
    DECLARE hidden INT DEFAULT 0;
    DECLARE created INT DEFAULT 0;
    DECLARE textbook_sets INT DEFAULT 0;
    DECLARE cards INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        IF started = 1 THEN ROLLBACK; END IF;
        IF locked = 1 THEN DO RELEASE_LOCK(lock_name); END IF;
        RESIGNAL;
    END;
    IF DATABASE() IS NULL OR @@autocommit <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Select the database in a fresh autocommit connection';
    END IF;
    SET owner = (SELECT id FROM users WHERE email = @flashcard_textbook_owner_email ORDER BY id LIMIT 1);
    IF owner IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Owner account not found; run SET @flashcard_textbook_owner_email = ''<email>''; first';
    END IF;
    SET lock_name = CONCAT('jlas-flashcard-textbook-', LEFT(SHA2(DATABASE(), 256), 30));
    SELECT GET_LOCK(lock_name, 10) INTO locked;
    IF COALESCE(locked, 0) <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Another Flashcard textbook seed import is running';
    END IF;
    START TRANSACTION;
    SET started = 1;
    SET anchor = CURRENT_TIMESTAMP(6);

    -- 1. Bỏ dữ liệu flashcard cũ của các seed trước (và bộ giáo trình của bài không còn trong dữ liệu).
    DROP TEMPORARY TABLE IF EXISTS fct_old;
    CREATE TEMPORARY TABLE fct_old (set_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, in_game TINYINT NOT NULL) ENGINE=InnoDB;
    INSERT INTO fct_old (set_id, in_game)
    SELECT s.id, EXISTS (SELECT 1 FROM game_match g WHERE g.flashcard_set_id = s.id)
    FROM flashcard_set s JOIN users u ON u.id = s.owner_id
    WHERE s.deleted_at IS NULL AND (
          (s.moderation_summary = 'DEMO_FLASHCARD_5SETS'
           AND s.title COLLATE utf8mb4_bin NOT IN ('Hiragana cơ bản', 'Katakana cơ bản'))
       OR s.moderation_summary LIKE 'SEEDSQLFLASHCARD\_10\_%'
       OR (s.title COLLATE utf8mb4_bin = 'N5 giao tiếp cơ bản' AND s.visibility = 'PUBLIC'
           AND u.email IN ('demo@jlab.local', 'huyphw2@gmail.com'))
       OR (u.password_hash IS NULL AND u.google_id IS NULL AND EXISTS (
           SELECT 1 FROM fct_retired r WHERE r.owner_email = u.email AND r.title = s.title COLLATE utf8mb4_bin))
       OR (s.owner_id = owner AND s.moderation_summary LIKE 'TEXTBOOK\_FLASHCARD:%' AND NOT EXISTS (
           SELECT 1 FROM fct_set d WHERE d.kind = 'TEXTBOOK'
             AND s.moderation_summary = CONCAT('TEXTBOOK_FLASHCARD:', d.set_key))));
    SELECT COUNT(*), COALESCE(SUM(in_game), 0) INTO retired, hidden FROM fct_old;
    DELETE r FROM content_comment_rating r
        JOIN content_comment c ON c.id = r.comment_id
        JOIN fct_old o ON o.set_id = c.target_id
    WHERE c.target_type = 'FLASHCARD_SET';
    DELETE c FROM content_comment c JOIN fct_old o ON o.set_id = c.target_id WHERE c.target_type = 'FLASHCARD_SET';
    UPDATE flashcard_set s JOIN fct_old o ON o.set_id = s.id SET s.deleted_at = anchor WHERE o.in_game = 1;
    DELETE s FROM flashcard_set s JOIN fct_old o ON o.set_id = s.id WHERE o.in_game = 0;

    -- 2. Tìm bộ đã có: Hiragana/Katakana theo tên (giữ nguyên), bộ giáo trình theo mã bài rồi theo tên.
    UPDATE fct_set d SET d.set_id = (
        SELECT MIN(s.id) FROM flashcard_set s
        WHERE s.deleted_at IS NULL AND s.visibility = 'PUBLIC' AND s.title = d.title COLLATE utf8mb4_bin)
    WHERE d.kind = 'KANA';
    UPDATE fct_set d SET d.set_id = (
        SELECT MIN(s.id) FROM flashcard_set s
        WHERE s.owner_id = owner AND s.deleted_at IS NULL
          AND s.moderation_summary = CONCAT('TEXTBOOK_FLASHCARD:', d.set_key))
    WHERE d.kind = 'TEXTBOOK';
    UPDATE fct_set d SET d.set_id = (
        SELECT MIN(s.id) FROM flashcard_set s
        WHERE s.owner_id = owner AND s.deleted_at IS NULL AND s.title = d.title COLLATE utf8mb4_bin)
    WHERE d.kind = 'TEXTBOOK' AND d.set_id IS NULL;
    UPDATE flashcard_set s JOIN fct_set d ON d.set_id = s.id
    SET s.title = d.title, s.description = d.description,
        s.moderation_summary = CONCAT('TEXTBOOK_FLASHCARD:', d.set_key)
    WHERE d.kind = 'TEXTBOOK';

    -- 3. Tạo bộ còn thiếu; created_at lùi theo thứ tự để "Mới nhất" hiện N5 trước, bài 1 trước.
    UPDATE fct_set SET is_new = 1 WHERE set_id IS NULL;
    INSERT INTO flashcard_set (owner_id, folder_id, title, description, visibility, is_draft, moderation_status,
                               moderation_checked_at, moderation_summary, created_at, updated_at)
    SELECT owner, NULL, d.title, d.description, 'PUBLIC', 0, 'SAFE', anchor,
           IF(d.kind = 'TEXTBOOK', CONCAT('TEXTBOOK_FLASHCARD:', d.set_key), 'DEMO_FLASHCARD_5SETS'),
           anchor - INTERVAL d.sort_rank SECOND, anchor - INTERVAL d.sort_rank SECOND
    FROM fct_set d WHERE d.is_new = 1 ORDER BY d.sort_rank DESC;
    UPDATE fct_set d SET d.set_id = (
        SELECT MIN(s.id) FROM flashcard_set s
        WHERE s.owner_id = owner AND s.deleted_at IS NULL AND s.title = d.title COLLATE utf8mb4_bin
          AND s.moderation_summary = IF(d.kind = 'TEXTBOOK', CONCAT('TEXTBOOK_FLASHCARD:', d.set_key), 'DEMO_FLASHCARD_5SETS'))
    WHERE d.is_new = 1;
    SELECT COUNT(*) INTO created FROM fct_set WHERE is_new = 1;

    -- 4. Thẻ: cập nhật theo vị trí, thêm vị trí mới, bỏ vị trí thừa (bộ Hiragana/Katakana có sẵn để nguyên).
    UPDATE flashcard_card c
        JOIN fct_set d ON d.set_id = c.set_id
        JOIN fct_card x ON x.set_key = d.set_key AND x.position = c.position
    SET c.front = x.front, c.back = x.back, c.reading = x.reading, c.meaning = x.meaning, c.han_viet = x.han_viet,
        c.jlpt_level = x.jlpt_level, c.word_type = x.word_type, c.example_ja = x.example_ja, c.example_vi = x.example_vi
    WHERE d.kind = 'TEXTBOOK';
    DELETE c FROM flashcard_card c
        JOIN fct_set d ON d.set_id = c.set_id
        LEFT JOIN fct_card x ON x.set_key = d.set_key AND x.position = c.position
    WHERE d.kind = 'TEXTBOOK' AND x.set_key IS NULL;
    INSERT INTO flashcard_card (set_id, position, front, back, reading, meaning, han_viet, jlpt_level, word_type,
                                example_ja, example_vi)
    SELECT d.set_id, x.position, x.front, x.back, x.reading, x.meaning, x.han_viet, x.jlpt_level, x.word_type,
           x.example_ja, x.example_vi
    FROM fct_card x
        JOIN fct_set d ON d.set_key = x.set_key
        LEFT JOIN flashcard_card c ON c.set_id = d.set_id AND c.position = x.position
    WHERE c.id IS NULL AND (d.kind = 'TEXTBOOK' OR d.is_new = 1)
    ORDER BY d.sort_rank, x.position;
    SELECT COUNT(*) INTO textbook_sets FROM fct_set WHERE kind = 'TEXTBOOK';
    SELECT COUNT(*) INTO cards FROM fct_card;

    COMMIT;
    SET started = 0;
    DO RELEASE_LOCK(lock_name);
    SET locked = 0;
    DROP TEMPORARY TABLE IF EXISTS fct_old;
    SELECT retired AS old_sets_removed, hidden AS old_sets_hidden_for_game_history, textbook_sets AS textbook_sets,
           created AS sets_created, cards AS cards_in_payload;
END$$
DELIMITER ;

CALL jlas_seed_flashcard_textbook_v1();
DROP PROCEDURE IF EXISTS jlas_seed_flashcard_textbook_v1;
DROP TEMPORARY TABLE IF EXISTS fct_set;
DROP TEMPORARY TABLE IF EXISTS fct_card;
DROP TEMPORARY TABLE IF EXISTS fct_retired;
